import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Events","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/attribute/events.md","filePath":"en/modules/attribute/events.md","lastUpdated":0}`),a={name:`en/modules/attribute/events.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to “Events”">​</a></h1><p>All event classes are in <code>emaki.jiuwu.craft.attribute.api.event</code>. They are synchronous, cancellable Bukkit events dispatched on the owner thread of the live target (damage uses the owner shared by the combatants), and published only while runtime holds the required live target. Wrong-thread facade calls fail before creating an event</p><table tabindex="0"><thead><tr><th>Event</th><th>Timing</th><th>Cancellable</th><th>Mutable field</th><th>Cancellation/effect</th></tr></thead><tbody><tr><td><code>PlayerResourceConsumeEvent</code></td><td>After validation, before a custom resource is deducted</td><td>Yes</td><td><code>amount</code></td><td>Prevents consumption; a replacement amount is revalidated against the current balance</td></tr><tr><td><code>PlayerAttributePointAllocateEvent</code></td><td>After validation, before points are spent</td><td>Yes</td><td><code>amount</code></td><td>Prevents allocation; replacement amount is revalidated against available points</td></tr><tr><td><code>PlayerAttributePointResetEvent</code></td><td>After validation, before points are refunded or a reset point is spent</td><td>Yes</td><td>None</td><td>Prevents the reset, refund, and reset-point cost</td></tr><tr><td><code>EmakiAttributeDamageEvent</code></td><td>After damage calculation, before final damage is applied</td><td>Yes</td><td><code>finalDamage</code></td><td>Cancellation or a final damage <code>&lt;= 0</code> prevents EmakiAttribute damage application</td></tr></tbody></table><p>The remaining fields are read-only snapshots; values modified by a listener are revalidated after the listener returns. Non-owner or async paths must not fire a Bukkit event off-thread; schedule on the owner scheduler when you need reliable interception. These are runtime-produced event contracts, not extension interfaces; contribution providers and gates live in <code>emaki.jiuwu.craft.attribute.api.extension</code></p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};